def __init__(self, key):
        if not 4 <= len(key) <= 56:
            raise ValueError("Blowfish key must contain 4..56 bytes")
        self.p = list(P_INIT)
        self.s = [list(s) for s in (S0_INIT,S1_INIT,S2_INIT,S3_INIT)]
        for i in range(18):
            word = 0
            for j in range(4):
                word = (word << 8) | key[(4*i+j) % len(key)]
            self.p[i] ^= word
        left = right = 0
        for table in [self.p] + self.s:
            for i in range(0,len(table),2):
                left,right = self._words(left,right)
                table[i],table[i+1] = left,right

def _f(self, x):
        a,b,c,d = x >> 24, (x >> 16) & 255, (x >> 8) & 255, x & 255
        return (((self.s[0][a] + self.s[1][b]) ^ self.s[2][c]) + self.s[3][d]) & 0xffffffff

