def _cast_block(block, setup, decrypt=False):
    if len(block) != 8:
        raise ValueError("CAST block must contain 8 bytes")
    km, kr, rounds = setup
    left, right = struct.unpack('>II', block)
    for i in (range(rounds-1,-1,-1) if decrypt else range(rounds)):
        if i % 3 == 0:
            v = _rotl(km[i] + right, kr[i])
        elif i % 3 == 1:
            v = _rotl(km[i] ^ right, kr[i])
        else:
            v = _rotl(km[i] - right, kr[i])
        a,b,c,d = v >> 24, (v >> 16) & 255, (v >> 8) & 255, v & 255
        if i % 3 == 0:
            f = ((S1[a] ^ S2[b]) - S3[c] + S4[d]) & MASK
        elif i % 3 == 1:
            f = (((S1[a] - S2[b] + S3[c]) & MASK) ^ S4[d]) & MASK
        else:
            f = (((S1[a] + S2[b]) ^ S3[c]) - S4[d]) & MASK
        left, right = right, left ^ f
    return struct.pack('>II', right, left)

def cast_encrypt(plaintext, password):
    data = plaintext.encode() if isinstance(plaintext, str) else plaintext
    padding = 8 - len(data) % 8
    data += bytes([padding]) * padding
    setup = cast_setup(derive_key(password))
    return b''.join(_cast_block(data[i:i+8], setup) for i in range(0,len(data),8))

