def gost_round(a, k):
    # 1. Modular addition (a + k) mod 2^32
    s = (a + k) & 0xffffffff
    # 2. Eight 4-to-4 S-boxes
    out = 0
    for i in range(8):
        nibble = (s >> (4 * i)) & 0x0f
        out |= (GOST_SBOXES[i][nibble] << (4 * i))
    # 3. 11-bit cyclic left rotation
    return ((out << 11) & 0xffffffff) | (out >> 21)

def get_subkey(key_words, round_idx):
    if round_idx < 24:
        # First 24 rounds: K0..K7 three times
        return key_words[round_idx % 8]
    else:
        # Last 8 rounds: K7..K0 in reverse order
        return key_words[7 - (round_idx % 8)]

