def quadratic_function(x):
    # f(x) = (x * (2*x + 1)) mod 2^32
    # followed by cyclic rotation left by 5 bits
    val = (x * ((2 * x + 1) & 0xffffffff)) & 0xffffffff
    return rotl32(val, 5)

